// MCP server on stdio (JSON-RPC 2.0, one message per line), dual-era: 2026-07-28 clients discover it and send the
// protocol version with every request; older clients use the initialize handshake. Every command is a tool.
// Generated by anything-anything from anything.toml.
import { createInterface } from "node:readline";
import { argsFrom, commands } from "./cli.ts";
import { registry } from "./commands/index.ts";
import manifest from "./manifest.json" with { type: "json" };

const SUPPORTED = ["2026-07-28", "2025-11-25", "2025-06-18", "2025-03-26"];
const VERSION_KEY = "io.modelcontextprotocol/protocolVersion";

type Message = { id?: unknown; method?: string; params?: Record<string, unknown> };
type Reply = Record<string, unknown>;

const info = () => ({ name: manifest.name, version: manifest.version });

function error(id: unknown, code: number, message: string, data?: unknown): Reply {
  return { jsonrpc: "2.0", id, error: data === undefined ? { code, message } : { code, message, data } };
}

async function call(name: string, args: Record<string, unknown>): Promise<Reply | null> {
  const command = commands.find((c) => c.tool === name);
  const run = command && registry[command.module];
  if (!command || !run) return null;
  try {
    const out = await run(argsFrom(command, args));
    const text = out.text || JSON.stringify(out.data, null, 2);
    const result: Reply = { resultType: "complete", content: [{ type: "text", text }], isError: false };
    if (out.data !== null && out.data !== undefined) result.structuredContent = out.data;
    return result;
  } catch (e) {
    const text = e instanceof Error ? e.message : String(e);
    return { resultType: "complete", content: [{ type: "text", text }], isError: true };
  }
}

export async function handle(msg: Message): Promise<Reply | null> {
  if (!("id" in msg)) return null;
  const id = msg.id;
  const params = msg.params ?? {};
  const meta = (params._meta ?? {}) as Record<string, unknown>;
  const version = meta[VERSION_KEY];
  if (typeof version === "string" && !SUPPORTED.includes(version)) {
    return error(id, -32022, "Unsupported protocol version", { supported: SUPPORTED, requested: version });
  }
  let result: Reply;
  switch (msg.method) {
    case "server/discover":
      result = {
        resultType: "complete",
        supportedVersions: SUPPORTED,
        capabilities: { tools: {} },
        instructions: manifest.instructions,
        ttlMs: 3_600_000,
        cacheScope: "public",
        _meta: { "io.modelcontextprotocol/serverInfo": info() },
      };
      break;
    case "initialize": {
      const asked = typeof params.protocolVersion === "string" ? params.protocolVersion : "2025-11-25";
      result = {
        protocolVersion: SUPPORTED.includes(asked) ? asked : "2025-11-25",
        capabilities: { tools: {} },
        serverInfo: info(),
        instructions: manifest.instructions,
      };
      break;
    }
    case "ping":
      result = {};
      break;
    case "tools/list":
      result = { resultType: "complete", tools: manifest.tools, ttlMs: 300_000, cacheScope: "public" };
      break;
    case "tools/call": {
      const name = String(params.name ?? "");
      const called = await call(name, (params.arguments ?? {}) as Record<string, unknown>);
      if (!called) return error(id, -32602, `unknown tool ${name}`);
      result = called;
      break;
    }
    default:
      return error(id, -32601, `unknown method ${msg.method}`);
  }
  return { jsonrpc: "2.0", id, result };
}

export async function serve(): Promise<void> {
  const lines = createInterface({ input: process.stdin, crlfDelay: Number.POSITIVE_INFINITY });
  for await (const line of lines) {
    if (!line.trim()) continue;
    let reply: Reply | null;
    try {
      reply = await handle(JSON.parse(line) as Message);
    } catch (e) {
      reply = error(null, -32700, e instanceof Error ? e.message : String(e));
    }
    if (reply) process.stdout.write(`${JSON.stringify(reply)}\n`);
  }
}
